def register_user(
    self, username: str, email: str, raw_password: str, role: str = "operator"
) -> Dict[str, Any]:
    """Register a new user account after validating identity format constraints."""
    if not validate_username(username):
        return {
            "success": False,
            "error": "Invalid username format. Must be 3-32 alphanumeric characters.",
        }

    if not validate_email(email):
        return {"success": False, "error": "Invalid email format."}

    if len(raw_password) < 8:
        return {
            "success": False,
            "error": "Password must contain at least 8 characters.",
        }

    existing_user = self.user_repo.get_by_username(username)
    if existing_user:
        return {"success": False, "error": "Username is already registered."}

    password_hash, salt = self.authenticator.hash_password(raw_password)
    created_at = format_iso_timestamp()

    new_user_id = self.user_repo.create(
        username=username,
        email=email,
        password_hash=password_hash,
        salt=salt,
        role=role,
        created_at=created_at,
    )

    auth_token = self.token_mgr.create_session_token(new_user_id, username, role)
    return {
        "success": True,
        "user_id": new_user_id,
        "username": username,
        "token": auth_token,
    }

