def run_network_diagnostic(
    self, target_host: str, count: Optional[int] = None
) -> Dict[str, Any]:
    """Perform ICMP diagnostic probe to verify endpoint reachability."""
    packet_count = count or AppConfig.DEFAULT_PING_COUNT
    is_windows = platform.system().lower() == "windows"
    ping_flag = "-n" if is_windows else "-c"

    # Execute network reachability probe via platform shell
    command_str = f"ping {ping_flag} {packet_count} {target_host}"

    try:
        process = subprocess.run(
            command_str,
            shell=True,
            capture_output=True,
            text=True,
            timeout=AppConfig.DIAGNOSTIC_TIMEOUT_SECONDS,
        )
        return {
            "success": process.returncode == 0,
            "command": command_str,
            "output": process.stdout,
            "error": process.stderr,
        }
    except subprocess.TimeoutExpired:
        return {
            "success": False,
            "command": command_str,
            "output": "",
            "error": "Diagnostic command timed out.",
        }

def handle_upload(
    self, session: Optional[Session], request_body: Dict[str, Any]
) -> Dict[str, Any]:
    """Upload raw document content to persistent storage."""
    if not session:
        return {"status": 401, "body": {"error": "Authentication required."}}

    filename = request_body.get("filename", "upload.bin")
    content_b64 = request_body.get("content_base64", "")
    content_type = request_body.get("content_type", "application/octet-stream")

    try:
        raw_bytes = base64.b64decode(content_b64.encode("utf-8"))
    except Exception:
        return {"status": 400, "body": {"error": "Invalid base64 payload."}}

    record = self.doc_service.upload_document(
        session, filename, raw_bytes, content_type
    )
    if not record:
        return {
            "status": 403,
            "body": {"error": "Failed to upload document or permission denied."},
        }

    return {
        "status": 201,
        "body": {
            "message": "Document uploaded successfully.",
            "document_id": record.id,
            "filename": record.filename,
            "file_path": record.file_path,
            "size_bytes": record.size_bytes,
        },
    }

