        self.token_mgr = token_mgr or TokenManager()

    def register_user(
        self, username: str, email: str, raw_password: str, role: str = "operator"
    ) -> Dict[str, Any]:
        """Register a new user account after validating identity format constraints."""
        if not validate_username(username):
            return {
                "success": False,
                "error": "Invalid username format. Must be 3-32 alphanumeric characters.",
            }

        if not validate_email(email):
            return {"success": False, "error": "Invalid email format."}

        if len(raw_password) < 8:
            return {
                "success": False,
                "error": "Password must contain at least 8 characters.",
            }

        existing_user = self.user_repo.get_by_username(username)
        if existing_user:
            return {"success": False, "error": "Username is already registered."}

        password_hash, salt = self.authenticator.hash_password(raw_password)
        created_at = format_iso_timestamp()

        new_user_id = self.user_repo.create(
            username=username,
            email=email,
            password_hash=password_hash,
            salt=salt,
            role=role,
            created_at=created_at,
        )

        auth_token = self.token_mgr.create_session_token(new_user_id, username, role)
        return {
            "success": True,
            "user_id": new_user_id,
            "username": username,
            "token": auth_token,
        }

    def get_user_profile(self, user_id: int) -> Optional[Dict[str, Any]]:
        """Fetch sanitized public representation of a user profile."""
        user = self.user_repo.get_by_id(user_id)
        if not user:
            return None
        return user.to_public_dict()

    def update_email_address(self, user_id: int, new_email: str) -> Dict[str, Any]:
        """Update email contact information for an account."""
        if not validate_email(new_email):
            return {"success": False, "error": "Invalid email address format."}

        updated = self.user_repo.update_email(user_id, new_email)
        return {"success": updated}

    def change_user_password(
        self, user_id: int, old_password: str, new_password: str
    ) -> Dict[str, Any]:
        """Verify previous password and update security credentials."""
        user = self.user_repo.get_by_id(user_id)
        if not user:
            return {"success": False, "error": "User record not found."}

        if not self.authenticator.verify_password(
            old_password, user.password_hash, user.password_salt
        ):
            return {"success": False, "error": "Current password verification failed."}

        if len(new_password) < 8:
            return {
                "success": False,
                "error": "New password does not meet complexity requirements.",
            }

        new_hash, new_salt = self.authenticator.hash_password(new_password)
        success = self.user_repo.update_password(user_id, new_hash, new_salt)
        return {"success": success}

    def deactivate_account(self, user_id: int) -> bool:
        """Disable access privileges for a user account."""
        return self.user_repo.set_active_status(user_id, False)

    def list_system_users(self) -> List[Dict[str, Any]]:
        """Retrieve sanitized user listings for directory display."""
        users = self.user_repo.list_all()
        return [u.to_public_dict() for u in users]

