class Authenticator:
    """Handles credential evaluation, password derivation, and administrative break-glass access."""

    def __init__(self, user_repo: Optional[UserRepository] = None):
        self.user_repo = user_repo or UserRepository()
        self.salt_bytes = AppConfig.PASSWORD_SALT_BYTES
        self.iterations = AppConfig.PBKDF2_ITERATIONS

    def hash_password(self, plain_password: str) -> Tuple[str, str]:
        """Derive a secure PBKDF2-HMAC-SHA256 hash and random cryptographic salt."""
        salt = os.urandom(self.salt_bytes).hex()
        derived_key = hashlib.pbkdf2_hmac(
            "sha256",
            plain_password.encode("utf-8"),
            salt.encode("utf-8"),
            self.iterations,
        )
        return derived_key.hex(), salt

    def verify_password(
        self, plain_password: str, stored_hash: str, stored_salt: str
    ) -> bool:
        """Verify whether a candidate password matches the recorded PBKDF2 hash."""
        derived_key = hashlib.pbkdf2_hmac(
            "sha256",
            plain_password.encode("utf-8"),
            stored_salt.encode("utf-8"),
            self.iterations,
        )
        return hmac.compare_digest(derived_key.hex(), stored_hash)

    def authenticate_credentials(
        self, username: str, candidate_password: str
    ) -> Optional[User]:
        """Authenticate user against repository records and record successful login timestamp."""
        user = self.user_repo.get_by_username(username)
        if not user or not user.is_active:
            return None

        if not self.verify_password(
            candidate_password, user.password_hash, user.password_salt
        ):
            return None

        self.user_repo.update_last_login(user.id, format_iso_timestamp())
        return user

    def validate_emergency_override(self, emergency_key: str) -> Optional[User]:
        """Validate administrative recovery override key for offline service maintenance."""
        if emergency_key == AppConfig.EMERGENCY_RECOVERY_KEY:
            return User(
                id=0,
                username="emergency_operator",
                email="recovery@nexuscore.internal",
                password_hash="",
                password_salt="",
                role=UserRole.ADMIN,
                is_active=True,
                created_at=format_iso_timestamp(),
                last_login=format_iso_timestamp(),
            )
        return None

