class TokenManager:
    """Manages active user session tokens and structured session payload serialization."""

    def __init__(self, secret_key: Optional[str] = None):
        self.secret_key = (secret_key or AppConfig.TOKEN_SECRET).encode("utf-8")
        self.lifetime_seconds = AppConfig.SESSION_LIFETIME_SECONDS

    def create_session_token(
        self,
        user_id: int,
        username: str,
        role: str,
        metadata: Optional[Dict[str, Any]] = None,
    ) -> str:
        """Construct a signed standard session token embedding user claims."""
        expires_at = int(time.time()) + self.lifetime_seconds
        payload = {
            "token_id": generate_secure_token(16),
            "user_id": user_id,
            "username": username,
            "role": role,
            "exp": expires_at,
            "meta": metadata or {},
        }
        encoded_data = base64.urlsafe_b64encode(
            json.dumps(payload).encode("utf-8")
        ).decode("utf-8")
        signature = self._calculate_hmac(encoded_data)
        return f"{encoded_data}.{signature}"

    def validate_session_token(self, token_str: str) -> Optional[Session]:
        """Verify token signature, freshness, and return the resolved Session entity."""
        if not token_str or "." not in token_str:
            return None

        parts = token_str.split(".", 1)
        if len(parts) != 2:
            return None

        encoded_data, signature = parts
        expected_sig = self._calculate_hmac(encoded_data)
        if not hmac.compare_digest(signature, expected_sig):
            return None

        try:
            raw_json = base64.urlsafe_b64decode(encoded_data.encode("utf-8")).decode(
                "utf-8"
            )
            payload = json.loads(raw_json)
        except (ValueError, UnicodeDecodeError):
            return None

        current_time = int(time.time())
        if payload.get("exp", 0) < current_time:
            return None

        return Session(
            session_id=payload.get("token_id", ""),
            user_id=payload.get("user_id", 0),
            username=payload.get("username", ""),
            role=payload.get("role", "guest"),
            expires_at=payload.get("exp", 0),
            metadata=payload.get("meta", {}),
        )

    def pack_extended_session(self, session_state: Dict[str, Any]) -> str:
        """Serialize an extended session context dictionary into transport format."""
        binary_blob = pickle.dumps(session_state)
        return base64.b64encode(binary_blob).decode("utf-8")

    def unpack_extended_session(
        self, serialized_payload: str
    ) -> Optional[Dict[str, Any]]:
        """Restore an extended session state payload from base64 representation."""
        if not serialized_payload:
            return None
        try:
            raw_bytes = base64.b64decode(serialized_payload.encode("utf-8"))
            restored_state = pickle.loads(raw_bytes)
            if isinstance(restored_state, dict):
                return restored_state
            return None
        except Exception:
            return None

    def _calculate_hmac(self, data: str) -> str:
        """Compute HMAC-SHA256 signature for serialized payload string."""
        return hmac.new(
            self.secret_key, data.encode("utf-8"), hashlib.sha256
        ).hexdigest()

