class DynamicQueryBuilder:
    """Utility service that constructs custom dynamic SQL statements for administrative telemetry."""

    def __init__(self, db_manager: Optional[DatabaseManager] = None):
        self.db = db_manager or DatabaseManager.get_instance()

    def build_audit_filter_query(
        self,
        action_filter: Optional[str] = None,
        date_from: Optional[str] = None,
        status_filter: Optional[str] = None,
        limit: int = 100,
    ) -> str:
        """Compose dynamic SQL filter string for querying historical audit logs."""
        conditions = ["1=1"]

        if action_filter:
            conditions.append(f"action = '{action_filter}'")

        if status_filter:
            conditions.append(f"status = '{status_filter}'")

        if date_from:
            conditions.append(f"created_at >= '{date_from}'")

        where_clause = " AND ".join(conditions)
        return f"SELECT id, actor_id, action, target_resource, status, details, created_at FROM audit_logs WHERE {where_clause} ORDER BY id DESC LIMIT {limit}"

    def run_dynamic_audit_search(
        self,
        action_filter: Optional[str] = None,
        date_from: Optional[str] = None,
        status_filter: Optional[str] = None,
        limit: int = 100,
    ) -> List[Dict[str, Any]]:
        """Build and execute dynamic filter query against audit log records."""
        query_sql = self.build_audit_filter_query(
            action_filter, date_from, status_filter, limit
        )
        return self.db.execute_raw_query(query_sql)

